import React, { useState, useEffect } from 'react';
import { toast } from 'react-toastify';
import api from '../../services/api';
import AdminCard from '../common/AdminCard';

const AdminSettings = () => {
  const [settings, setSettings] = useState({
    site_name: 'SC Academy',
    site_description: '',
    logo_url: '',
    favicon_url: '',
    address: '',
    phone: '',
    email: '',
    facebook_url: '',
    telegram_url: '',
    youtube_url: '',
    google_map_url: '',
  });
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    fetchSettings();
  }, []);

  const fetchSettings = async () => {
    try {
      const response = await api.get('/api/settings/');
      if (response.data) {
        setSettings(response.data);
      }
    } catch (error) {
      toast.error('Failed to load settings');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      await api.put('/api/settings/', settings);
      toast.success('Settings updated successfully');
    } catch (error) {
      toast.error('Failed to update settings');
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center py-12">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-900"></div>
      </div>
    );
  }

  return (
    <div>
      <h1 className="text-3xl font-bold text-blue-900 mb-6">Settings</h1>

      <form onSubmit={handleSubmit}>
        <div className="space-y-6">
          {/* Site Information */}
          <AdminCard className="p-6">
            <h2 className="text-xl font-bold text-blue-900 mb-4">Site Information</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="admin-label">Site Name</label>
                <input
                  type="text"
                  value={settings.site_name || ''}
                  onChange={(e) => setSettings({ ...settings, site_name: e.target.value })}
                  className="admin-input"
                />
              </div>
              <div>
                <label className="admin-label">Site Description</label>
                <input
                  type="text"
                  value={settings.site_description || ''}
                  onChange={(e) => setSettings({ ...settings, site_description: e.target.value })}
                  className="admin-input"
                />
              </div>
            </div>
          </AdminCard>

          {/* Contact Information */}
          <AdminCard className="p-6">
            <h2 className="text-xl font-bold text-blue-900 mb-4">Contact Information</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="admin-label">Phone</label>
                <input
                  type="text"
                  value={settings.phone || ''}
                  onChange={(e) => setSettings({ ...settings, phone: e.target.value })}
                  className="admin-input"
                />
              </div>
              <div>
                <label className="admin-label">Email</label>
                <input
                  type="email"
                  value={settings.email || ''}
                  onChange={(e) => setSettings({ ...settings, email: e.target.value })}
                  className="admin-input"
                />
              </div>
              <div className="md:col-span-2">
                <label className="admin-label">Address</label>
                <input
                  type="text"
                  value={settings.address || ''}
                  onChange={(e) => setSettings({ ...settings, address: e.target.value })}
                  className="admin-input"
                />
              </div>
            </div>
          </AdminCard>

          {/* Social Media */}
          <AdminCard className="p-6">
            <h2 className="text-xl font-bold text-blue-900 mb-4">Social Media</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="admin-label">Facebook URL</label>
                <input
                  type="url"
                  value={settings.facebook_url || ''}
                  onChange={(e) => setSettings({ ...settings, facebook_url: e.target.value })}
                  className="admin-input"
                  placeholder="https://facebook.com/..."
                />
              </div>
              <div>
                <label className="admin-label">Telegram URL</label>
                <input
                  type="url"
                  value={settings.telegram_url || ''}
                  onChange={(e) => setSettings({ ...settings, telegram_url: e.target.value })}
                  className="admin-input"
                  placeholder="https://t.me/..."
                />
              </div>
              <div>
                <label className="admin-label">YouTube URL</label>
                <input
                  type="url"
                  value={settings.youtube_url || ''}
                  onChange={(e) => setSettings({ ...settings, youtube_url: e.target.value })}
                  className="admin-input"
                  placeholder="https://youtube.com/..."
                />
              </div>
              <div>
                <label className="admin-label">Google Maps URL</label>
                <input
                  type="url"
                  value={settings.google_map_url || ''}
                  onChange={(e) => setSettings({ ...settings, google_map_url: e.target.value })}
                  className="admin-input"
                  placeholder="https://maps.google.com/..."
                />
              </div>
            </div>
          </AdminCard>

          {/* Media URLs */}
          <AdminCard className="p-6">
            <h2 className="text-xl font-bold text-blue-900 mb-4">Media URLs</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="admin-label">Logo URL</label>
                <input
                  type="url"
                  value={settings.logo_url || ''}
                  onChange={(e) => setSettings({ ...settings, logo_url: e.target.value })}
                  className="admin-input"
                  placeholder="https://example.com/logo.png"
                />
              </div>
              <div>
                <label className="admin-label">Favicon URL</label>
                <input
                  type="url"
                  value={settings.favicon_url || ''}
                  onChange={(e) => setSettings({ ...settings, favicon_url: e.target.value })}
                  className="admin-input"
                  placeholder="https://example.com/favicon.ico"
                />
              </div>
            </div>
          </AdminCard>

          <div className="flex justify-end">
            <button
              type="submit"
              disabled={saving}
              className={`admin-btn-primary px-8 py-3 text-lg ${
                saving ? 'opacity-50 cursor-not-allowed' : ''
              }`}
            >
              {saving ? (
                <span className="flex items-center space-x-2">
                  <svg className="animate-spin h-5 w-5" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  <span>Saving...</span>
                </span>
              ) : (
                'Save Settings'
              )}
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

export default AdminSettings;
